import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[32768];
        private int ptr = 0;
        private int count = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (ptr >= count) {
                count = in.read(buffer, 0, buffer.length);
                if (count <= 0) return -1;
                ptr = 0;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            byte b = read();
            while (b <= ' ' && b != -1) {
                b = read();
            }
            if (b == -1) return -1;
            boolean neg = false;
            if (b == '-') {
                neg = true;
                b = read();
            }
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = read();
            }
            return neg ? -res : res;
        }
    }

    // Estrutura para representar a árvore como lista de adjacência compacta
    static class Tree {
        int n;
        int[] head;
        int[] to;
        int[] next;
        int edgeCount;

        Tree(int n) {
            this.n = n;
            head = new int[n + 1];
            java.util.Arrays.fill(head, -1);
            to = new int[2 * n];
            next = new int[2 * n];
            edgeCount = 0;
        }

        void addEdge(int u, int v) {
            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        int findCenter() {
            int[] dist = new int[n + 1];
            int[] parent = new int[n + 1];
            int[] queue = new int[n + 1];

            // 1ª BFS a partir do vértice 1
            int u = bfs(1, dist, null, queue);

            // 2ª BFS a partir de u
            int v = bfs(u, dist, parent, queue);

            // Reconstrói o caminho de v até u
            int pathLen = dist[v];
            int steps = pathLen / 2;
            int curr = v;
            for (int i = 0; i < steps; i++) {
                curr = parent[curr];
            }
            return curr;
        }

        private int bfs(int start, int[] dist, int[] parent, int[] queue) {
            java.util.Arrays.fill(dist, -1);
            int headQ = 0, tailQ = 0;

            queue[tailQ++] = start;
            dist[start] = 0;
            if (parent != null) parent[start] = 0;

            int farthestNode = start;
            int maxDist = 0;

            while (headQ < tailQ) {
                int curr = queue[headQ++];
                if (dist[curr] > maxDist) {
                    maxDist = dist[curr];
                    farthestNode = curr;
                }

                for (int e = head[curr]; e != -1; e = next[e]) {
                    int neighbor = to[e];
                    if (dist[neighbor] == -1) {
                        dist[neighbor] = dist[curr] + 1;
                        if (parent != null) parent[neighbor] = curr;
                        queue[tailQ++] = neighbor;
                    }
                }
            }
            return farthestNode;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        if (n == -1) return;
        int m = scanner.nextInt();

        Tree circle = new Tree(n);
        for (int i = 0; i < n - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            circle.addEdge(u, v);
        }

        Tree square = new Tree(m);
        for (int i = 0; i < m - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            square.addEdge(u, v);
        }

        int centerCircle = circle.findCenter();
        int centerSquare = square.findCenter();

        System.out.println(centerCircle + " " + centerSquare);
    }
}
